using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Reflection;using System.ComponentModel;using System.Windows.Forms;
namespace GearLab {public static class Robot672LifecycleTests {
 static int checks;static string progressFile;static void Check(bool b,string s){checks++;if(progressFile!=null)File.AppendAllText(progressFile,DateTime.UtcNow.ToString("O")+" "+s+" => "+b+Environment.NewLine);if(!b)throw new Exception(s);}
 static void Wait(Func<bool> f){var w=System.Diagnostics.Stopwatch.StartNew();while(!f()&&w.Elapsed.TotalSeconds<90){Application.DoEvents();Thread.Sleep(15);}Check(f(),"operation completed");}
 static void Pump(){var end=DateTime.UtcNow.AddMilliseconds(150);Wait(()=>DateTime.UtcNow>end);}
 static object Call(object target,string name,params object[] args){return target.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(target,args);}
 public static int Core(string folder){Directory.CreateDirectory(folder);checks=0;try{
  string file=Path.Combine(folder,"tiny.robot.json");new RobotDocument().Save(file);int defaults=0;var fallback=new RobotDocument();var loaded=RobotDesignerForm.LoadInitialRobotDocument(file,()=>{defaults++;return fallback;});Check(defaults==0&&loaded!=null,"explicit project does not load default project first");Check(ReferenceEquals(fallback,RobotDesignerForm.LoadInitialRobotDocument(null,()=>{defaults++;return fallback;}))&&defaults==1,"new project invokes default factory once");
  var shape=new MechanismPart{Id="test_block",Name="Atomic export block",Kind="block",SizeX=20,SizeY=15,Length=10};var project=new MechanismProject();project.Parts.Add(shape);var model=new CadAssembly();model.Parts.Add(MechanismCad.BuildPart(project,shape));string step=Path.Combine(folder,"atomic.step");RobotDesignerForm.WriteRobotStepSnapshot(model,step);byte[] previous=File.ReadAllBytes(step);Check(Encoding.ASCII.GetString(previous).StartsWith("ISO-10303-21;"),"atomic STEP writes actual model");model.Parts[0].MeshOverride=new SceneMesh();bool failed=false;try{RobotDesignerForm.WriteRobotStepSnapshot(model,step);}catch{failed=true;}Check(failed&&previous.SequenceEqual(File.ReadAllBytes(step)),"failed STEP preserves previous target");Check(!Directory.GetFiles(folder,".gearlab-step-*.step").Any(),"failed STEP cleans staging file");File.WriteAllText(Path.Combine(folder,"lifecycle672-core-results.txt"),"PASS "+checks+" checks: lazy loading and atomic STEP export",Encoding.UTF8);return 0;
 }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"lifecycle672-core-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 public static int Run(string folder){Directory.CreateDirectory(folder);checks=0;progressFile=Path.Combine(folder,"lifecycle-progress.txt");RobotDesignerForm.CloseTrace=text=>File.AppendAllText(progressFile,text+Environment.NewLine);var deadline=new System.Threading.Timer(_=>{try{File.AppendAllText(Path.Combine(folder,"lifecycle-timeout.txt"),"owned test deadline");}catch{}Environment.Exit(2);},null,120000,System.Threading.Timeout.Infinite);var previousSink=UiMessage.TestSink;UiMessage.TestSink=text=>File.AppendAllText(Path.Combine(folder,"Robot672LifecycleTests.cs.dialogs.txt"),text+Environment.NewLine);var old=AppSettings.Current;string oldProfile=Environment.GetEnvironmentVariable("GEARLAB_PROFILE_DIR");try{
  Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",Path.Combine(Path.GetFullPath(folder),"profile-lifecycle672"));AppSettings.Current=new AppSettings{AutoSave=true,AutoSaveSeconds=600};
  string root=Path.GetDirectoryName(Application.ExecutablePath);string file=Path.Combine(root,"examples","Reference67.robot.json");if(!File.Exists(file))file=Path.Combine(Path.GetDirectoryName(root),"examples","Reference67.robot.json");
  using(var r=new RobotDesignerForm(file))using(var shell=new WorkspaceShell(r)){shell.Show();Wait(()=>r.Scene.Ready&&r.WebScene.Ready);Pump();int clears=r.WebScene.ClearCount,uploads=r.WebScene.PartUploadCount,passes=r.WebGeometryUploadPasses;var build=r.Build;Check(passes==1,"initial geometry uploaded exactly once");Call(r,"RenderWebRobot");Call(r,"RenderWebRobot");Check(r.WebScene.ClearCount==clears&&r.WebScene.PartUploadCount==uploads,"same model refresh does not reload WebGL geometry");
   var draft=AppSettings.Current.Clone();draft.AnimationScale=.75;draft.Language=GearLanguage.English;draft.Colors["Viewport"]="#263443";AppSettings.Commit(draft);Pump();Check(ReferenceEquals(build,r.Build)&&r.WebScene.ClearCount==clears&&r.WebScene.PartUploadCount==uploads,"appearance and playback settings retain robot geometry");draft=AppSettings.Current.Clone();draft.Quality=draft.Quality==GearQuality.Подробный?GearQuality.Обычный:GearQuality.Подробный;AppSettings.Commit(draft);Wait(()=>r.Scene.Ready);Pump();Check(ReferenceEquals(build,r.Build)&&r.WebScene.ClearCount==clears&&r.WebScene.PartUploadCount==uploads,"WPF quality completion does not reload WebGL model");
   for(int i=0;i<5;i++)Check(!r.TryRecoverRobot(),"unchanged recovery skipped");Check(r.RecoverySerializationCount==0&&r.RecoveryWriteCount==0,"initial idle recovery performs no serialization or disk write");r.SetGripperOpening(2);Check(r.TryRecoverRobot(),"changed pose checkpoint written");Check(r.RecoverySerializationCount==1&&r.RecoveryWriteCount==1,"one serialization per changed checkpoint");string recovered=Directory.GetFiles(AppSettings.Folder,"recovery-robot-*.json").Single();Check(RobotDocument.Parse(File.ReadAllText(recovered)).GripperOpening==2,"recovery stores current gripper despite compact history");for(int i=0;i<8;i++)r.TryRecoverRobot();Check(r.RecoverySerializationCount==1&&r.RecoveryWriteCount==1,"dirty idle document is not repeatedly serialized");r.SetGripperOpening(26);Check(r.TryRecoverRobot()&&RobotDocument.Parse(File.ReadAllText(recovered)).GripperOpening==26,"later pose writes latest checkpoint");Call(r,"Undo");Call(r,"Undo");Check(r.Document.GripperOpening==20&&r.TryRecoverRobot()&&RobotDocument.Parse(File.ReadAllText(recovered)).GripperOpening==20,"undo to saved state replaces the stale recovery pose");r.SetGripperOpening(26);
   var j=r.Document.Joints[1];r.JogJoint(j.Id,5);double position=j.Position;string name=j.Name;j.Name=name+" renamed";Call(r,"PropertyChanged","Name",TypeDescriptor.GetProperties(j)["Name"],name);Wait(()=>r.Scene.Ready);Call(r,"Undo");Wait(()=>r.Scene.Ready);Check(r.Document.Joints[1].Name==name&&r.Document.Joints[1].Position==position,"structural property undo retains preceding manual pose");
   build=r.Build;clears=r.WebScene.ClearCount;uploads=r.WebScene.PartUploadCount;typeof(RobotDesignerForm).GetField("phase",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(r,.35);var expected=RobotKinematics.Evaluate(r.Document,.35,true);var snapshot=r.CaptureRobotExportSnapshot(false,null);Check(r.Document.Joints.All(x=>Math.Abs(x.Position-expected[x.Id].Value)<1e-8),"export captures animated pose");Check(ReferenceEquals(build,r.Build)&&r.WebScene.ClearCount==clears&&r.WebScene.PartUploadCount==uploads,"animated export snapshot avoids geometry rebuild");
   using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim())using(var timer=new System.Windows.Forms.Timer{Interval=20}){int ticks=0;timer.Tick+=(s,e)=>ticks++;timer.Start();var task=r.WriteRobotExportAsync(snapshot,Path.Combine(folder,"async-marker.txt"),false,(m,p)=>{entered.Set();if(!release.Wait(10000))throw new TimeoutException();File.WriteAllText(p,"complete");});try{Wait(()=>entered.IsSet);Pump();Check(ticks>1&&r.RobotExportBusy,"export worker leaves UI responsive");Check(!((IWorkspaceDocument)r).WorkspaceCanClose(),"workspace refuses close while exporting");var duplicate=r.WriteRobotExportAsync(snapshot,"unused",true,(m,p)=>{});Check(duplicate.IsFaulted,"parallel export is rejected");}finally{release.Set();}Wait(()=>task.IsCompleted);task.GetAwaiter().GetResult();Check(!r.RobotExportBusy&&File.ReadAllText(Path.Combine(folder,"async-marker.txt"))=="complete","completed export clears shared guard");}
   var failing=r.WriteRobotExportAsync(snapshot,"unused",false,(m,p)=>{throw new IOException("expected test failure");});Wait(()=>failing.IsCompleted);Check(failing.IsFaulted&&!r.RobotExportBusy,"failed export clears guard");shell.ApproveTestClose();shell.Close();}
  File.WriteAllText(Path.Combine(folder,"lifecycle672-results.txt"),"PASS "+checks+" checks: geometry refresh, settings, idle recovery, animation snapshots, responsive export and close guards",Encoding.UTF8);return 0;
 }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"lifecycle672-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}finally{RobotDesignerForm.CloseTrace=null;deadline.Dispose();UiMessage.TestSink=previousSink;AppSettings.Current=old;Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",oldProfile);}}
}}
